        <Message
            at="2026-06-22T08:10:41.201026Z"
        >
            <Origin>019eee60-fb8b-71a7-a148-ee26b43c3590</Origin>
            <Speaker>$[[ Claude ]]( Dougs Claude )</Speaker>
            <Paragraph>
                Конечно, Ана 😊 Давай сделаю тебе свой простой рецепт под то, что у тебя есть и как ты хочешь — морковь,
                чеснок, куриный кубик, рис. И главное — разберёмся с рисом так, чтобы он получился. Раз у тебя круглозёрный
                рис, у меня хорошая новость: он <Word>
                    <Bold />
                    прощает ошибки
                </Word> лучше длинного, и для «мягкого, чуть разваренного» он идеален.
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    Сначала про рис — отвечу на твои вопросы прямо:
                </Word>
            </Paragraph>
            <Paragraph>
                <List />
                <Line>
                    <Word>
                        <Bold />
                        Промывать?
                    </Word> Да, обязательно. Круглозёрный рис очень крахмалистый, и если не промыть — будет клейкий комок.
                    Промывай в миске под холодной водой, меняя воду 3-4 раза, пока вода не станет почти прозрачной. Это твоя
                    страховка от «слипся в кашу».
                </Line>
                <Line>
                    <Word>
                        <Bold />
                        Обжаривать рис?
                    </Word> Да, мы его слегка обжарим вместе с морковью — это как раз помогает зёрнам не развалиться
                    полностью и впитать вкус. Тебе подходит.
                </Line>
                <Line>
                    <Word>
                        <Bold />
                        Сколько воды?
                    </Word> Для круглозёрного: <Word>
                        <Bold />
                        на 1 часть риса — 2 части воды.
                    </Word> Например, 1 стакан риса = 2 стакана воды. Раз ты хочешь «лучше мягкий, чем твёрдый» — можешь
                    взять <Word>
                        <Bold />
                        2,25 стакана воды
                    </Word>, будет нежнее.
                </Line>
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    Теперь твой рецепт по шагам.
                </Word> Возьмём 1 стакан риса (хватит на 2-3 порции):
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    Шаг 1. Подготовка.
                </Word> Промой 1 стакан риса (3-4 раза, до прозрачной воды), оставь в сите стекать. Морковь почисти и нарежь
                кубиками. Чеснок — 2-3 зубчика — порежь мелко или раздави.
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    Шаг 2. Чеснок на масле.
                </Word> В сковороду (где есть крышка!) или кастрюлю с толстым дном налей масла, чтобы покрыло дно. Нагрей на
                среднем огне, кинь чеснок. Жарь <Word>
                    <Bold />
                    30-60 секунд
                </Word>, только пока пойдёт аромат — не дай ему потемнеть, иначе будет горчить. Как запахло — можешь вынуть
                чеснок (если хочешь только аромат масла) или оставить.
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    Шаг 3. Морковь.
                </Word> В это же масло кинь морковь. Обжаривай 5-7 минут на среднем огне, помешивая, пока станет мягче и
                чуть золотистой.
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    Шаг 4. Рис обжарить.
                </Word> Добавь промытый стёкший рис к моркови. Помешивай 2 минуты — зёрна станут чуть прозрачными по краям.
                Это тот самый шаг, который спасает от «каши».
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    Шаг 5. Вода + кубик.
                </Word> Влей <Word>
                    <Bold />
                    2 стакана горячей воды
                </Word> (или 2,25 для мягкости). Раскроши туда куриный кубик, размешай, чтобы разошёлся. Попробуй воду —
                если кубик солёный, соль уже не нужна.
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    Шаг 6. Самое важное — варка.
                </Word> Доведи до кипения. Как закипело — <Word>
                    <Bold />
                    убавь огонь до минимума, накрой крышкой
                </Word> и не трогай <Word>
                    <Bold />
                    15 минут.
                </Word> Не открывай, не мешай — рису нужен пар. Это ключ к успеху.
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    Шаг 7. Отдых.
                </Word> Через 15 минут выключи огонь и дай постоять под крышкой ещё <Word>
                    <Bold />
                    5 минут.
                </Word> Потом открой, перемешай вилкой. Готово.
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    Три правила, которые решают твою проблему с рисом:
                </Word>
            </Paragraph>
            <Paragraph>
                <List ordered />
                <Line>Промыть до прозрачной воды (не будет клейстера).</Line>
                <Line>Точная вода: 1 риса : 2 воды.</Line>
                <Line>
                    На минимальном огне под крышкой 15 минут <Word>
                        <Bold />
                        не открывать
                    </Word> — рис варится паром, а не кипятком.
                </Line>
            </Paragraph>
            <Paragraph>
                Если что-то пойдёт не так по ходу — пиши прямо в процессе, я подскажу 😊 Например, если через 15 минут вода
                не вся впиталась, а рис уже мягкий — просто слей лишнюю и дай постоять. Если наоборот, жёсткий, а вода
                кончилась — добавь полстакана горячей воды и ещё 5 минут под крышкой.
            </Paragraph>
            <Paragraph>Удачи! Расскажешь потом, как вышло?</Paragraph>
        </Message>
